 View sleepCard(){LinearLayout b=col();sleepEditor=col();int a=p.getInt(key("sleep_hour"),0),c=p.getInt(key("sleep_minute"),30),d=p.getInt(key("wake_hour"),8),e=p.getInt(key("wake_minute"),0);sleepEditor.addView(timeRow("睡",a,c,true));View line=new View(this);line.setBackgroundColor(LINE);sleepEditor.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));sleepEditor.addView(timeRow("起",d,e,false));b.addView(sleepEditor);sleepDur=t("共 -- 小时 -- 分钟",17,true,INK);sleepDur.setGravity(Gravity.CENTER);sleepDur.setPadding(dp(10),dp(12),dp(10),dp(12));sleepDur.setBackground(round(LIME));sleepDur.setOnClickListener(v->toggleSleepLock());b.addView(sp(8));b.addView(sleepDur);sleepConfirm=btn("",Color.WHITE,INK);sleepConfirm.setVisibility(View.GONE);b.addView(sleepConfirm,new LinearLayout.LayoutParams(-1,1));boolean locked=p.getBoolean(key("sleep_confirmed"),false);setSleepEnabled(!locked);NumberPicker.OnValueChangeListener li=(x,o,n)->{if(rendering)return;p.edit().putInt(key("sleep_hour"),sh.getValue()).putInt(key("sleep_minute"),sm.getValue()).putInt(key("wake_hour"),wh.getValue()).putInt(key("wake_minute"),wm.getValue()).apply();updateSleep();updateAll();};sh.setOnValueChangedListener(li);sm.setOnValueChangedListener(li);wh.setOnValueChangedListener(li);wm.setOnValueChangedListener(li);return card(b,Color.WHITE);}
