 LinearLayout timeRow(String l,int h,int m,boolean sleep){LinearLayout r=row();r.addView(t(l,20,true,INK),new LinearLayout.LayoutParams(dp(48),-2));NumberPicker hp=picker(0,23,h),mp=picker(0,59,m);if(sleep){sh=hp;sm=mp;}else{wh=hp;wm=mp;}r.addView(hp,new LinearLayout.LayoutParams(0,dp(112),1));TextView colon=t(":",30,true,INK);colon.setGravity(Gravity.CENTER);r.addView(colon,new LinearLayout.LayoutParams(dp(28),dp(112)));r.addView(mp,new LinearLayout.LayoutParams(0,dp(112),1));return r;}
